run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_site_map" babappa build-site-map --sim-dir "$WORKSPACE/sim_low_short_6taxa" --align-dir "$WORKSPACE/align_low_short_6taxa" --outdir "$WORKSPACE/site_map_low_short_6taxa" --methods "$METHODS" --workers "$THREADS"
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_method_policy" babappa aligner-method-policy --align-dir "$WORKSPACE/align_low_short_6taxa" --site-map-dir "$WORKSPACE/site_map_low_short_6taxa" --outdir "$WORKSPACE/method_policy_low_short_6taxa" --max-conflict-fraction 0.03 --max-frame-error-fraction 0.0 --max-method-failure-fraction 0.01
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_tensors" babappa build-tensors --sim-dir "$WORKSPACE/sim_low_short_6taxa" --align-dir "$WORKSPACE/align_low_short_6taxa" --outdir "$WORKSPACE/tensors_low_short_6taxa" --methods "$METHODS" --workers "$THREADS"
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_index" babappa index-dataset --tensor-dir "$WORKSPACE/tensors_low_short_6taxa" --outdir "$WORKSPACE/dataset_low_short_6taxa" --methods "$METHODS" --workers "$THREADS"
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_labels" babappa extract-branch-site-labels --dataset-dir "$WORKSPACE/dataset_low_short_6taxa" --site-map-dir "$WORKSPACE/site_map_low_short_6taxa" --outdir "$WORKSPACE/labels_low_short_6taxa" --truth-mode explicit --aligned-site-mode mapped --foreground-source truth --streaming-output
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_branch_dataset" babappa build-branch-site-dataset --dataset-dir "$WORKSPACE/dataset_low_short_6taxa" --branch-site-labels "$WORKSPACE/labels_low_short_6taxa/branch_site_oracle_labels.tsv" --outdir "$WORKSPACE/branch_dataset_low_short_6taxa" --negative-downsample-ratio 5 --seed 42 --require-mappable-sites --streaming --max-output-rows 700000
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_short_6taxa_validate_branch_dataset" babappa validate-branch-site-dataset --branch-site-dataset-dir "$WORKSPACE/branch_dataset_low_short_6taxa"
cleanup_path "$WORKSPACE/sim_low_short_6taxa"; cleanup_path "$WORKSPACE/align_low_short_6taxa"; cleanup_path "$WORKSPACE/site_map_low_short_6taxa"; cleanup_path "$WORKSPACE/method_policy_low_short_6taxa"; cleanup_path "$WORKSPACE/tensors_low_short_6taxa"; cleanup_path "$WORKSPACE/dataset_low_short_6taxa"; cleanup_path "$WORKSPACE/labels_low_short_6taxa"

echo "--- chunk low_compact_8taxa: families=5000 taxa=8 codons=240 ---"
