run_once "$PLAN_DIR/stage_markers/.stage_complete_low_merge" babappa merge-branch-site-datasets --dataset-dirs "$WORKSPACE/branch_dataset_low_short_6taxa,$WORKSPACE/branch_dataset_low_compact_8taxa,$WORKSPACE/branch_dataset_low_standard_12taxa,$WORKSPACE/branch_dataset_low_long_20taxa,$WORKSPACE/branch_dataset_low_very_long_32taxa" --outdir "$WORKSPACE/branch_site_dataset_low_merged"
run_once "$PLAN_DIR/stage_markers/.stage_complete_low_train" babappa train-branch-site-neural --branch-site-dataset-dir "$WORKSPACE/branch_site_dataset_low_merged" --outdir "$WORKSPACE/branch_site_neural_low" --device "$DEVICE" --batch-size "$BATCH_SIZE" --threads "$THREADS" --feature-policy "$FEATURE_POLICY" --epochs 10 --learning-rate 0.001 --weight-decay 0.0001 --hidden-dim 64 --dropout 0.1 --positive-class-weight auto --monitor-metric val_auroc --max-train-items 300000 --max-val-items 75000 --max-calib-items 75000 --max-test-items 75000
